"""
    Python equivalent to TypeScripts >>> operator.

    @see https://stackoverflow.com/questions/5832982/how-to-get-the-logical-right-binary-shift-in-python
    """
def rshift(val: Any, n: Any) -> object {
    return ((val % 4294967296) >> n);
